insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('compliance', 'intermediate', 'module', 'm01-the-inspection-and-test-plan', 1, 'BLOCKING_POINT_TYPES is the qualityAssurance list of the point types that stop work. What does it hold?', '["Hold point and Witness point, the two types at which a test is watched.", "Hold point, and no other type.", "Hold point, Witness point and Review point, the three types a verifier signs.", "Every point type whose planned date has passed at the as-of date."]'::jsonb, 1, 'The list holds one entry. On QAP-2026-014 the stops work column reads true on the five hold point rows and false on every other row, and the engine derives the column from the type.'),
  ('compliance', 'intermediate', 'module', 'm01-the-inspection-and-test-plan', 2, 'At the as-of date 2026-10-15, H-08 reads Pending, planned 2026-10-20, overdue false. Is it one of the three in hold points outstanding 3?', '["No. A hold point joins the outstanding count only once its planned date has passed.", "No. The three are H-05, S-10 and R-12, the overdue points.", "No. Only a hold point that has Failed is counted as outstanding before closure.", "Yes. It is unresolved, and that count does not read the planned date."]'::jsonb, 3, 'The three are H-05, H-08 and H-11, the hold point rows whose resolved column reads false. H-08 and H-11 read overdue false and still stop work; being outstanding and being overdue are two separate readings.'),
  ('compliance', 'intermediate', 'module', 'm01-the-inspection-and-test-plan', 3, 'H-08, the hydrostatic test, is asked to pass with nobody named. Which sentence does canDecideCheckpoint refuse with?', '["A hold point needs the date it was verified and who verified it. Without those it has not been held.", "Record the date this was decided and who decided it.", "Say why this point is being waived.", "Accepted is not a checkpoint status."]'::jsonb, 0, 'The shorter sentence about the date and who decided it is the one W-09, a witness point, meets. The requirement under both is the same pair, a date and a person, and the hold point sentence adds that without them the point has not been held.'),
  ('compliance', 'intermediate', 'module', 'm01-the-inspection-and-test-plan', 4, 'W-09 is asked to be waived with a reason and no date or verifier, and the engine refuses. What does a waiver need on the record before it is allowed?', '["A reason alone, since the reason is the part of a waiver that an auditor can test.", "A date and who decided it, with the reason optional on a point that does not stop work.", "A date, who decided it, and the reason for the waiver.", "A reason and a second verifier."]'::jsonb, 2, 'The refusal for this request is "Record the date this was decided and who decided it." and the refusal for a waiver with no reason is the waiver sentence. Only with all three does the digest print ALLOWED.'),
  ('compliance', 'intermediate', 'module', 'm01-the-inspection-and-test-plan', 5, 'Does canDecideCheckpoint allow a hold point to be waived?', '["No. A hold point may be Passed or set Not applicable, and Waived is refused for it.", "Only while its plan is still a Draft, the same stage at which it may be removed.", "Yes, with a date, a verifier and a reason on the record.", "Only after it has first Failed."]'::jsonb, 2, 'H-08 waived with a date, a verifier and a reason is ALLOWED. The digest states that canDecideCheckpoint has no rule that forbids waiving a hold point, and a waived hold point with its record and reason is resolved like any waived point.'),
  ('compliance', 'intermediate', 'module', 'm01-the-inspection-and-test-plan', 6, 'H-11, the pre-commissioning release, is to be set Not applicable. In what order does canDecideCheckpoint ask for what it needs?', '["The date and the name first, then the reason.", "The reason first, then the date and the name.", "All three at once, in one refusal.", "The verifier, then the date, then the reason."]'::jsonb, 0, 'With nothing recorded the engine refuses on the date and the name, the same record a waiver needs. Given those two, it refuses again until a reason says why the hold point does not apply. H-11 with all three reads ALLOWED.'),
  ('compliance', 'intermediate', 'module', 'm01-the-inspection-and-test-plan', 7, 'S-10, site surveillance, reads In progress and overdue true. It is set Not applicable with nothing recorded. What does the engine answer?', '["REFUSED, because S-10 reads overdue true against its planned date of 2026-10-01.", "REFUSED, because setting any point aside needs the date and who decided it.", "ALLOWED once a reason is recorded, the same record H-11 needs.", "ALLOWED, with nothing asked of it."]'::jsonb, 3, 'A surveillance point stops nothing, and the digest prints ALLOWED for S-10 with nothing recorded: no date, no name and no reason. Not applicable is one of the three statuses in CHECKPOINT_RESOLVED_STATUSES. The same request on H-11, a hold point, is refused until a date, a name and a reason are on the record.'),
  ('compliance', 'intermediate', 'module', 'm01-the-inspection-and-test-plan', 8, 'Which of these points is inside planProgress''s resolved 6 at the as-of date?', '["H-05, which reads Failed.", "W-06, the coating holiday test, which reads Waived.", "S-10, site surveillance, which reads In progress.", "R-12, the as-built dossier review, which reads Notified."]'::jsonb, 1, 'The resolved six are H-01, W-02, H-03 and R-04, which Passed, W-06, which is Waived, and M-07, which is Not applicable. H-05 Failed and is outstanding.'),
  ('compliance', 'intermediate', 'module', 'm01-the-inspection-and-test-plan', 9, 'H-05 reads Failed at the as-of date. How does planProgress count it?', '["In failed 1, and again among the outstanding 6.", "In failed 1 alone.", "Among the resolved 6.", "In outstanding 6 alone."]'::jsonb, 0, 'A failure does not finish a point. H-05 is not in the resolved list, it is the failed 1, and it is one of the outstanding six with H-08, W-09, S-10, H-11 and R-12.'),
  ('compliance', 'intermediate', 'module', 'm01-the-inspection-and-test-plan', 10, 'SECTION 11 prints four cases of how a planProgress percent rounds. Which pairing is one of them?', '["5 of 8 prints 58.", "1 of 8 prints 63.", "3 of 8 prints 38.", "23 of 40 prints 13."]'::jsonb, 2, 'The four cases are 1 of 8 prints 13, 23 of 40 prints 58, 3 of 8 prints 38 and 5 of 8 prints 63. planProgress rounds half up on the exact fraction of resolved points, and a percent is quoted as the engine prints it.'),
  ('compliance', 'intermediate', 'module', 'm01-the-inspection-and-test-plan', 11, 'planProgress is asked about a plan with no points. What does it print for the percent?', '["0.", "50.", "It refuses to count an empty plan.", "null."]'::jsonb, 3, 'An empty plan has no fraction to take, and planProgress over a plan with no points prints percent null. A screen that shows 0 there, or the 50 that QAP-2026-014 reads, has invented a figure the engine does not make.'),
  ('compliance', 'intermediate', 'module', 'm01-the-inspection-and-test-plan', 12, 'Between the as-of date reading, resolved 6 and percent 50, and the allowed closure step, resolved 9 of 12 and percent 75, which three points were resolved?', '["W-09, S-10 and R-12, the three the closure walk reached last.", "H-05, H-08 and H-11, all three of them hold points.", "H-08, H-11 and S-10.", "H-05, S-10 and R-12, the three points that read overdue true."]'::jsonb, 1, 'At the allowed step W-09, S-10 and R-12 are still unresolved. The walk re-inspects H-05 and passes H-08 and H-11, and none of the three unresolved types stops work.'),
  ('compliance', 'intermediate', 'module', 'm01-the-inspection-and-test-plan', 13, 'A reviewer asks canDecideCheckpoint to set a point to Accepted. What happens?', '["It records the point as Passed.", "It refuses: Accepted is not a checkpoint status.", "It allows it and counts it resolved.", "It refuses until a date and a verifier are recorded beside the word."]'::jsonb, 1, 'The checkpoint vocabulary is a fixed list: Pending, Notified, In progress, Passed, Failed, Waived and Not applicable. A word outside it is refused before it reaches the record.'),
  ('compliance', 'intermediate', 'module', 'm01-the-inspection-and-test-plan', 14, 'H-08 is asked to pass with nobody named, and the engine refuses. What is H-08''s status after the refused request?', '["Passed.", "In progress.", "Failed.", "Pending."]'::jsonb, 3, 'A request is not a result. A refused request changes nothing on the plan, so H-08 keeps the status it had at the as-of date.'),
  ('compliance', 'intermediate', 'module', 'm01-the-inspection-and-test-plan', 15, 'W-06 is Waived and H-01 Passed. What does planProgress''s percent 50 tell a reader about the difference between them?', '["Nothing. Both are inside resolved 6 and count alike.", "That W-06 counts as half a point.", "That W-06 is left out of total 12.", "That W-06 is still outstanding."]'::jsonb, 0, 'Passed, Waived and Not applicable are the three resolved statuses and each counts alike. The percent says how many points no longer need anything; the status column, and the reason on the waiver, say which were checked.'),
  ('compliance', 'intermediate', 'module', 'm02-closing-a-plan', 1, 'QAP-2026-014 is asked to close as recorded at the as-of date. What does canClosePlan refuse on first?', '["The 3 hold points outstanding.", "The 3 open NCRs against it.", "The one failed checkpoint, H-05.", "The 3 overdue points, H-05, S-10 and R-12, in planned date order."]'::jsonb, 2, 'The first refusal is "1 checkpoint has failed and has not been resolved. A failed inspection is the most outstanding item on a plan." The hold point and NCR refusals come later in the walk, and S-10 and R-12, both overdue, never stop it.'),
  ('compliance', 'intermediate', 'module', 'm02-closing-a-plan', 2, 'With H-05 re-inspected and Passed, the refusal reads "2 hold points still outstanding (H-08, H-11)." Why is the count 2 when planProgress printed hold points outstanding 3 at the as-of date?', '["H-05 was the third, and the re-inspection resolved it.", "The gate counts only hold points that are also overdue at the as-of date.", "The gate leaves out a hold point whose planned date falls after the as-of date.", "planProgress counts H-01 as outstanding."]'::jsonb, 0, 'At the as-of date the three were H-05, H-08 and H-11. H-08 and H-11 both read overdue false and are still named, so the planned date plays no part in the count.'),
  ('compliance', 'intermediate', 'module', 'm02-closing-a-plan', 3, 'The same plan has every hold point Passed and every NCR closed, and W-09, a Witness point, reads Failed. What does canClosePlan answer?', '["ALLOWED, since a witness point does not stop work.", "REFUSED, with the hold point sentence naming W-09.", "ALLOWED, and planProgress keeps W-09 in failed 1.", "REFUSED, with the failed checkpoint sentence H-05 met."]'::jsonb, 3, 'The digest fails W-09, R-04, M-07 and S-10 one at a time and each is refused with "1 checkpoint has failed and has not been resolved." A failed point blocks closure whatever its type, including the types whose stops work column reads false.'),
  ('compliance', 'intermediate', 'module', 'm02-closing-a-plan', 4, 'The third refusal reads "3 non-conformances raised against this plan are still open." Which NCR statuses does the plan gate treat as open?', '["Open alone.", "Actions in progress, Open and Disposition agreed.", "Every status except Closed, so a Voided NCR is still counted as open.", "Open and Actions in progress, since Disposition agreed has settled the item."]'::jsonb, 1, 'The three rows reading open true are NCR-2026-031, Actions in progress, NCR-2026-027, Open, and NCR-2026-019, Disposition agreed. Closed and Voided read open false.'),
  ('compliance', 'intermediate', 'module', 'm02-closing-a-plan', 5, 'S-10 and R-12 read overdue true at the as-of date. Does canClosePlan stop on either of them?', '["No. The plan closes with both still unresolved.", "Yes. An overdue point blocks closure.", "Only R-12, a Notified point.", "Only S-10, since site surveillance runs until the work ends."]'::jsonb, 0, 'The walk reaches ALLOWED with W-09, S-10 and R-12 still unresolved. The gate reads failed points, hold points outstanding and open NCRs, and S-10 and R-12 are none of those.'),
  ('compliance', 'intermediate', 'module', 'm02-closing-a-plan', 6, 'The plan''s points are summarised under the plan marked Closed. Which count keeps a value above zero?', '["outstanding, still 6.", "overdue, still 3.", "failed, which still reads 1.", "None of them; a Closed plan reports every count as 0."]'::jsonb, 2, 'The Closed line reads outstanding 0, overdue 0, failed 1. The closed status stops the engine reporting anything as outstanding or overdue, and the failure count survives it.'),
  ('compliance', 'intermediate', 'module', 'm02-closing-a-plan', 7, 'H-08, a pending hold point, is asked to be removed from the Active plan and is refused. Where does the refusal send the request?', '["To waiving it, with a date, a verifier and a reason on the record.", "To returning the plan to Draft first.", "To raising an NCR against the plan for it.", "To recording it Not applicable with the reason."]'::jsonb, 3, 'The refusal reads "A hold point cannot be removed once its plan has left Draft. Record it as Not applicable with the reason, so the plan shows who set it aside and why." The plan workflow has no move from Active back to Draft.'),
  ('compliance', 'intermediate', 'module', 'm02-closing-a-plan', 8, 'R-04, a review point that Passed, is asked to be removed from the Active plan. Why does canRemoveCheckpoint refuse?', '["It is a review point, and review points stop work once the plan is Active.", "It has a result recorded, and a recorded result is evidence that stays on the plan.", "The plan has left Draft, and no point of any type may leave an Active plan.", "It is resolved, and removing it would lower the plan''s percent."]'::jsonb, 1, 'The refusal reads "Item R-04 has a result recorded (Passed). A recorded result is evidence and stays on the plan." W-09, a pending witness point, may be removed from the same Active plan.'),
  ('compliance', 'intermediate', 'module', 'm02-closing-a-plan', 9, 'W-09, a pending witness point, may be removed from the Active plan. When is the same removal refused?', '["While the plan is Active, since W-09 is still Pending.", "Once the plan has left Draft, as for a hold point.", "Never, since a witness point stops no work.", "Once the plan is Closed."]'::jsonb, 3, 'The refusal on the Closed plan reads "This plan is closed. Its inspection points are the record it was finished on." A closed plan is frozen.'),
  ('compliance', 'intermediate', 'module', 'm02-closing-a-plan', 10, 'Which request to raise an NCR does canRaiseNcr refuse?', '["One raised against QAP-2026-014 once it is Closed.", "One raised against no plan at all.", "One raised against the Active plan while H-05 reads Failed.", "One raised against the Active plan while 3 NCRs are open."]'::jsonb, 0, 'Against the Active plan and against no plan are both ALLOWED. Against the Closed plan the refusal reads "QAP-2026-014 is closed. Raise the non-conformance against the plan now in force, or with no plan."'),
  ('compliance', 'intermediate', 'module', 'm02-closing-a-plan', 11, 'In nextPlanStatuses, from which status may a plan move to Closed?', '["Active or Under review.", "Any status that is not final.", "Active only.", "Draft, once every hold point is resolved."]'::jsonb, 2, 'Active may move to Closed, Superseded or Cancelled. Asked to move Draft straight to Closed, canAdvancePlan refuses: "A plan that is draft can only move to Under review, Active, Cancelled."'),
  ('compliance', 'intermediate', 'module', 'm02-closing-a-plan', 12, 'Which plan statuses does nextPlanStatuses print as final?', '["Closed and Cancelled, since a Superseded plan may return to Active.", "Superseded, Closed and Cancelled.", "Closed alone, since a Cancelled plan may be reinstated as a Draft.", "Closed and Under review."]'::jsonb, 1, 'Superseded, Closed and Cancelled each print final. Under review may move to Active, Draft or Cancelled.'),
  ('compliance', 'intermediate', 'module', 'm02-closing-a-plan', 13, 'In what order does the closure walk meet canClosePlan''s three refusals?', '["Failed checkpoints, then hold points outstanding, then open NCRs.", "Hold points outstanding, then failed checkpoints, then open NCRs.", "Open NCRs, then failed checkpoints, then hold points outstanding.", "Failed checkpoints, then open NCRs, then hold points outstanding."]'::jsonb, 0, 'The counts in the refusals are 1, then 2, then 3, each the engine''s own at its step. The NCR check comes last, and it is the only one that reads a record outside the plan''s own points.'),
  ('compliance', 'intermediate', 'module', 'm02-closing-a-plan', 14, 'At the allowed step planProgress reads resolved 9 of 12 and percent 75. What does that percent leave unsaid?', '["That H-05 was re-inspected and failed a second time.", "That 3 NCRs are still open against the plan.", "That H-08 and H-11 are still pending.", "That W-09, S-10 and R-12 are still unresolved on a plan the engine lets close."]'::jsonb, 3, 'The allowed step comes after H-05, H-08 and H-11 are resolved and every NCR is closed or voided. A witness point, a surveillance point and a review point stand unresolved, because the gate asks only about failed points, hold points and NCRs.'),
  ('compliance', 'intermediate', 'module', 'm02-closing-a-plan', 15, 'SECTION 12 prints overdue 3 and hold points outstanding 3 for the plan. Which point sits in both lists?', '["H-08 and H-11.", "S-10 and R-12.", "H-05 alone.", "No point sits in both lists."]'::jsonb, 2, 'The overdue three are H-05, S-10 and R-12. The hold points outstanding are H-05, H-08 and H-11. Only H-05 is on both, and H-08 and H-11 block closure while reading overdue false.'),
  ('compliance', 'intermediate', 'module', 'm03-the-nonconformance', 1, 'A Major NCR with nothing recorded is asked to close. What does canCloseNcr ask for first?', '["A root cause, since a major non-conformance needs one before it closes.", "At least one corrective action that has been verified effective.", "The date the NCR was raised, so that its age can be read.", "The disposition: what happens to the non-conforming item."]'::jsonb, 3, 'The first refusal is "Agree the disposition first: what happens to the non-conforming item." It is the first refusal on the Major walk and on the Observation walk, and NCR-2026-027, a Minor NCR, meets it at the as-of date.'),
  ('compliance', 'intermediate', 'module', 'm03-the-nonconformance', 2, 'A Major NCR has its disposition recorded, Repair, and nothing else. What does canCloseNcr answer?', '["REFUSED: A major non-conformance needs a root cause before it closes.", "REFUSED: Record the date the disposition was agreed.", "ALLOWED, since Repair deals with the item and the cause together.", "REFUSED until a corrective action is raised."]'::jsonb, 1, 'A disposition is a decision and carries its date. Only with the disposition and its date on the record does the walk move on to the root cause.'),
  ('compliance', 'intermediate', 'module', 'm03-the-nonconformance', 3, 'summarise prints concessions 2 for the ABAM NCRs. Which two does it count?', '["NCR-2026-022, Use as is, and NCR-2026-006, Regrade, both of them Closed.", "NCR-2026-031, Repair, and NCR-2026-019, Return to supplier, both open.", "NCR-2026-019, Return to supplier, and NCR-2026-022, Use as is.", "NCR-2026-027 and NCR-2026-011, the two with no disposition recorded."]'::jsonb, 0, 'CONCESSION_DISPOSITIONS holds Use as is and Regrade. The count keeps a concession after its NCR closes, since it is the outcome that leaves a known departure from specification in service.'),
  ('compliance', 'intermediate', 'module', 'm03-the-nonconformance', 4, 'One corrective action is complete and has never been checked. At which severities does canCloseNcr refuse to close over it?', '["Critical alone.", "Critical, Major and Minor.", "Critical and Major.", "Every severity, Observation included."]'::jsonb, 2, 'NCR_EFFECTIVENESS_REQUIRED holds Critical and Major. On a Minor NCR the digest prints ALLOWED for one corrective action complete and never checked.'),
  ('compliance', 'intermediate', 'module', 'm03-the-nonconformance', 5, 'What may a Minor NCR close without, once its disposition and date are recorded?', '["Its disposition date.", "A root cause and any action at all.", "Nothing further; a Minor NCR walks the same steps as a Major one.", "A root cause, though it still needs one corrective action raised."]'::jsonb, 1, 'The Minor walk prints ALLOWED for no root cause and no actions, and ALLOWED for one corrective action complete and never checked. The one refusal it meets is an open action.'),
  ('compliance', 'intermediate', 'module', 'm03-the-nonconformance', 6, 'Which refusal do the Major walk and the Minor walk share?', '["Record the date the disposition was agreed.", "No corrective action has been verified effective yet.", "A major non-conformance needs at least one corrective action.", "1 corrective or preventive action still open."]'::jsonb, 3, 'An open action blocks closure at both severities, with the same sentence. It is also the refusal NCR-2026-031 meets at the as-of date, with k2 In progress.'),
  ('compliance', 'intermediate', 'module', 'm03-the-nonconformance', 7, 'NCR-2026-019 carries k3, which was checked and found ineffective. Why does canCloseNcr allow it at the as-of date?', '["k4, a second corrective action, is verified effective.", "Its disposition ends the matter.", "k3 is Complete, so it counts as working.", "At 117 days it is past the check."]'::jsonb, 0, 'The walked refusal for an NCR whose one corrective action was found not to work reads "Raise another one rather than closing over it." NCR-2026-019 has that second action, k4, and it was verified effective.'),
  ('compliance', 'intermediate', 'module', 'm03-the-nonconformance', 8, 'k2, the preventive action on NCR-2026-031, is marked Complete. Which refusal does NCR-2026-031 meet next?', '["1 corrective or preventive action still open.", "A corrective action here was checked and found not to have worked.", "No corrective action has been verified effective yet.", "Record the date the disposition was agreed."]'::jsonb, 2, 'Finishing k2 clears the open action and exposes the next gap: k1 is Complete and reads verified effective false. For a Major NCR the check that it worked is required.'),
  ('compliance', 'intermediate', 'module', 'm03-the-nonconformance', 9, 'A Major NCR has its preventive action finished and no corrective action. The refusal draws a line between two records. Which?', '["A preventive action deals with the cause; a corrective action deals with the record.", "A correction deals with the site; a disposition deals with the supplier.", "A root cause deals with the item; a corrective action deals with the date.", "A disposition deals with the item; a corrective action deals with the cause."]'::jsonb, 3, 'The refusal reads "A major non-conformance needs at least one corrective action. A disposition deals with the item; a corrective action deals with the cause."'),
  ('compliance', 'intermediate', 'module', 'm03-the-nonconformance', 10, 'To what date does ncrAgeDays measure a Closed NCR?', '["To its closed date.", "To the as-of date, the same as an open NCR.", "To its due date, where one is recorded.", "To the date its disposition was agreed."]'::jsonb, 0, 'ncrAgeDays measures to the as-of date while an NCR is open, and to the closed date once it is closed or voided. NCR-2026-022 was raised 2026-07-01 and closed 2026-07-09, and its age reads 8 on any date after that.'),
  ('compliance', 'intermediate', 'module', 'm03-the-nonconformance', 11, 'An NCR is 90 days old. Which band does ageBand put it in?', '["Over 90 days.", "61 to 90 days.", "31 to 60 days.", "null, since the band edges are exclusive."]'::jsonb, 1, 'Each band includes both of its printed ends: 90 days reads 61 to 90 days, and 91 is the first day Over 90 days. Only a negative age, -1, reads null.'),
  ('compliance', 'intermediate', 'module', 'm03-the-nonconformance', 12, 'The ncrAgeing grid shows a count of 1 in the band 31 to 60 days. Which NCR is it?', '["NCR-2026-006, the Minor NCR at 48 days.", "NCR-2026-027, the Minor NCR at 64 days.", "NCR-2026-031, at 43 days.", "NCR-2026-011, the Major NCR voided at 2."]'::jsonb, 2, 'ncrAgeing counts open NCRs only. NCR-2026-006 carries 48 days and the band 31 to 60 days in the age table, and it is Closed, so it is absent from the grid.'),
  ('compliance', 'intermediate', 'module', 'm03-the-nonconformance', 13, 'summarise prints mean open age 75 days. What is it taken over?', '["The three open ages, 43, 64 and 117.", "All six ages, the closed and voided ones included.", "The two serious NCRs.", "The two overdue NCRs."]'::jsonb, 0, 'The digest prints the ages the mean is taken over: 43, 64 and 117, their sum 224 over 3. The closed ages 8, 2 and 48 are not in it.'),
  ('compliance', 'intermediate', 'module', 'm03-the-nonconformance', 14, 'isCapaOpen reads true for k5, the corrective action on NCR-2026-011. Is k5 in the action summarise''s open 2?', '["Yes. summarise counts every open action.", "Yes, and in overdue 1 as well.", "No. open 2 counts Preventive actions only.", "No. Its NCR is Voided, and summarise leaves it out."]'::jsonb, 3, 'The open two are k2 and k6, and the overdue one is k2. The digest prints that summarise leaves k5 out of the open and overdue counts because it sits on NCR-2026-011, which is Voided.'),
  ('compliance', 'intermediate', 'module', 'm03-the-nonconformance', 15, 'The same actions summarised with no NCRs supplied print open 3 and overdue 2. What changed?', '["k1 is counted, never having been checked.", "k5 is counted, since its Voided parent was not supplied.", "k6 turns overdue with no NCR to hold it.", "k3 counts as open again."]'::jsonb, 1, 'The digest''s line reads "A child whose parent is not supplied counts." Without the NCRs the engine cannot know that k5''s parent is Voided, so the counts move from open 2 and overdue 1.'),
  ('compliance', 'intermediate', 'module', 'm04-the-checklist', 1, 'Items 9, 10 and 11 on AUD-2026-007 all carry the result Not applicable. Which of them reads answered true?', '["Item 9, which carries its reason.", "Item 11, the Critical one.", "Items 9 and 10, which have a note.", "All three of them."]'::jsonb, 0, 'Item 9''s note reads "No excavation open during the audit." Item 10''s note is blank and item 11 has none, and both read answered false. A blank note counts the same as a missing one.'),
  ('compliance', 'intermediate', 'module', 'm04-the-checklist', 2, 'checklistProgress prints notApplicable 3 and answered 10. Which figure includes items 10 and 11?', '["answered 10, which counts every row that carries a result of any kind.", "Both of them, since a Not applicable result is one of the four answers.", "notApplicable 3, which counts every Not applicable result.", "Neither; such an item is dropped."]'::jsonb, 2, 'notApplicable counts items 9, 10 and 11. answered 10 counts items 1 to 9 and 12, and leaves out 10 and 11 because a Not applicable with no reason is not an answer.'),
  ('compliance', 'intermediate', 'module', 'm04-the-checklist', 3, 'unansweredItems lists 10, 11, 13 and 14. What separates items 13 and 14 from items 10 and 11?', '["Items 13 and 14 are Critical questions, and 10 and 11 are Minor ones.", "Items 13 and 14 carry a blank note, and 10 and 11 carry no note.", "Items 13 and 14 read Observation, and 10 and 11 read Not applicable.", "Items 13 and 14 have no row at all; 10 and 11 have a row that is not an answer."]'::jsonb, 3, 'The digest prints that items 10 (Not applicable, a blank note) and 11 (Not applicable, no note) have a recorded row that is not an answer, and that items 13 and 14 have no row at all. Item 13 is Minor and item 14 Major.'),
  ('compliance', 'intermediate', 'module', 'm04-the-checklist', 4, 'Items 2 and 6 are answered Nonconformant. What do they do to checklistProgress''s percent 71?', '["They lower it, since the percent counts conformant answers.", "They raise it, exactly as a Conformant answer would.", "Nothing; a failed answer is outstanding.", "They are held out of it until a finding is raised from each."]'::jsonb, 1, 'The percent measures answering. Items 2 and 6 sit inside answered 10 beside the conformant 6 and the observation, so the percent says how much of the checklist has an accepted answer and says nothing about what conformed.'),
  ('compliance', 'intermediate', 'module', 'm04-the-checklist', 5, 'An audit has no checklist at all. What does checklistProgress print, and what should a screen show for it?', '["percent 0, shown as an empty bar on the audit''s screen.", "No figure, since checklistProgress refuses an audit with no checklist.", "percent 71, the figure carried over from AUD-2026-007.", "percent null, shown as no checklist to measure."]'::jsonb, 3, 'With no questions there is no fraction to take. planProgress over a plan with no points and programmeProgress over no audits print null in the same way.'),
  ('compliance', 'intermediate', 'module', 'm04-the-checklist', 6, 'AF-2026-018 was raised from item 2 and is then Voided. What does criticalAnswersWithoutFindings list?', '["Items 2 and 6.", "Item 6 alone, since item 2 keeps the finding raised from it.", "Item 2 alone, since voiding reopens only the finding''s own item.", "Nothing until the audit is reported."]'::jsonb, 0, 'With AF-2026-018 in force the list is 6. With it Voided the list is 2, 6: a voided finding covers nothing, and item 2 counts as uncovered exactly as though no finding had been raised.'),
  ('compliance', 'intermediate', 'module', 'm04-the-checklist', 7, 'A three-item checklist has a Major item and a Minor item answered Nonconformant, no finding raised, every item answered and a conclusion written. What does canReportAudit answer?', '["REFUSED, naming the Major item as needing a finding.", "REFUSED, naming both items as needing a finding.", "ALLOWED, and the report goes through.", "ALLOWED only once the Major item has a finding raised."]'::jsonb, 2, 'criticalAnswersWithoutFindings lists 0 items and the report is ALLOWED. The finding rule applies to Critical items only, and the engine has no rule that a Major or Minor nonconformance must raise a finding before the audit is reported.'),
  ('compliance', 'intermediate', 'module', 'm04-the-checklist', 8, 'The digest walks canRaiseFinding through three refusals before it reaches the stop-work rows. What do those three ask for?', '["A finding type, an owner and a due date.", "A finding type, a one-line statement and objective evidence.", "A one-line statement, a correction and a root cause.", "Objective evidence, a lead auditor and the auditee''s signature."]'::jsonb, 1, 'The three refusals are "Pick the finding type.", "State the finding in one line." and the objective evidence sentence. A number, an owner and a due date are what the reporting refusal says a failed critical question needs.'),
  ('compliance', 'intermediate', 'module', 'm04-the-checklist', 9, 'What does the canRaiseFinding refusal say objective evidence is?', '["What was seen, where, and when.", "Who saw it and who owns it.", "A photograph and a date.", "The clause and the gap."]'::jsonb, 0, 'The refusal reads "Objective evidence: what was seen, where, and when. It is the first thing an auditee will ask for." Item 2''s note, "No gas test entry for the 07:30 hot work.", is that kind of evidence.'),
  ('compliance', 'intermediate', 'module', 'm04-the-checklist', 10, 'A finding that stopped work is raised with the type Observation. What does canRaiseFinding answer?', '["ALLOWED, once the correction is recorded with it.", "ALLOWED, and it counts in stop-work open.", "REFUSED until the audit has been Reported.", "REFUSED, because it must be typed a nonconformity."]'::jsonb, 3, 'The engine''s own sentence is "A finding that stopped work is a nonconformity, not an observation." A stop-work nonconformity with its correction is ALLOWED.'),
  ('compliance', 'intermediate', 'module', 'm04-the-checklist', 11, 'A stop-work nonconformity is raised. What must it carry on the record at the moment it is raised?', '["A corrective action, with the root cause behind it.", "A check that the correction was effective.", "The correction: what was done about it at the time.", "The lead auditor''s name on the stop order."]'::jsonb, 2, 'The refusal reads "A finding that stopped work records what was done about it at the time. Imminent danger does not wait for the corrective action cycle." The correction is immediate; the corrective action runs on its own cycle.'),
  ('compliance', 'intermediate', 'module', 'm04-the-checklist', 12, 'A reported audit has a stop-work minor finding still open. What does canCloseAudit answer?', '["ALLOWED, since only major findings hold an audit open.", "REFUSED: 1 finding that stopped work is still open.", "ALLOWED, once the correction is on the finding.", "REFUSED until the finding is regraded as major."]'::jsonb, 1, 'The finding in that row is a minor one and it still holds the audit open. Having stopped work is enough for the gate, whatever the finding''s grade.'),
  ('compliance', 'intermediate', 'module', 'm04-the-checklist', 13, 'The programme summarise prints open findings 1, open major 1 and stop-work open 1. How many findings stand behind the three counts?', '["Three, one behind each of the three counts.", "Two: AF-2026-018 and a finding raised from item 6.", "One: AF-2026-018, a Minor nonconformity that stopped work.", "One: AF-2026-018, a Major nonconformity, Open, stop-work true."]'::jsonb, 3, 'The digest names the findings summarise counts: AF-2026-018 alone. One finding is behind open findings 1, open major 1 and stop-work open 1.'),
  ('compliance', 'intermediate', 'module', 'm04-the-checklist', 14, 'With every item answered and items 10 and 11 given reasons, canReportAudit refuses on critical item 6 alone. Why is item 2 not named?', '["Item 2 is covered by AF-2026-018.", "Item 2 is a Major question.", "Item 2''s note already records the time of the hot work.", "The refusal names only the last critical item that failed."]'::jsonb, 0, 'Items 2 and 6 are both Critical and both Nonconformant. criticalAnswersWithoutFindings with AF-2026-018 raised from item 2 lists 6, and the refusal reads "Critical item 6 was answered Nonconformant with no finding raised."'),
  ('compliance', 'intermediate', 'module', 'm04-the-checklist', 15, 'Item 11 is a Critical question that reads Not applicable with no note. Where does the engine list it at the as-of date?', '["In criticalAnswersWithoutFindings, beside item 6.", "Nowhere; it needs nothing more.", "In unansweredItems, beside 10, 13 and 14.", "Among the conformant 6, since nothing was found wrong."]'::jsonb, 2, 'Without its reason item 11 is not an answer, so it sits in unansweredItems and in outstanding 4. criticalAnswersWithoutFindings lists Critical items answered Nonconformant, and with AF-2026-018 raised from item 2 it lists 6 alone.'),
  ('compliance', 'intermediate', 'module', 'm05-the-audit-and-the-programme', 1, 'Once an audit is Reported, which move does nextAuditStatuses allow it?', '["Closed or Cancelled.", "Closed, and no other.", "Closed, or back to In progress for more fieldwork.", "Closed, Cancelled or Fieldwork complete."]'::jsonb, 1, 'Reported: Closed. Cancelled is reachable from Planned, In progress and Fieldwork complete, and once an audit is reported its only move is to Closed.'),
  ('compliance', 'intermediate', 'module', 'm05-the-audit-and-the-programme', 2, 'Which backward move does nextAuditStatuses allow?', '["Reported to Fieldwork complete.", "In progress to Planned.", "Closed to Reported.", "Fieldwork complete to In progress."]'::jsonb, 3, 'Fieldwork complete may move to Reported, In progress or Cancelled, so an auditor who finds a gap while writing up can return to the field. Closed and Cancelled are final.'),
  ('compliance', 'intermediate', 'module', 'm05-the-audit-and-the-programme', 3, 'A cancellation is asked for with a reason made of spaces. What does canCancelAudit answer?', '["REFUSED, with the same sentence as no reason at all.", "ALLOWED, since the reason field is not empty.", "ALLOWED, though the audit stays outstanding.", "REFUSED, with a sentence about blank text."]'::jsonb, 0, 'Both rows read "Say why this audit is not being done. An audit that quietly disappears from the programme is the reason a programme cannot be trusted." A reason of spaces counts as no reason.'),
  ('compliance', 'intermediate', 'module', 'm05-the-audit-and-the-programme', 4, 'AUD-2026-007 reads Fieldwork complete, planned end 2026-10-09, overdue true at the as-of date. Why is it still overdue with its fieldwork done?', '["Its checklist still has 4 items with no answer yet.", "Its stop-work finding, AF-2026-018, is still open.", "Its planned end has passed and it has not been Reported.", "The programme it belongs to has not been marked Complete."]'::jsonb, 2, 'isAuditOverdue reads true for Planned, In progress and Fieldwork complete once the planned end has passed, and false for Reported, Closed and Cancelled. The report is the deliverable.'),
  ('compliance', 'intermediate', 'module', 'm05-the-audit-and-the-programme', 5, 'In what order does canReportAudit refuse AUD-2026-007 on its walk from the record as it stands?', '["Unanswered items, then critical item 6 with no finding, then the conclusion.", "Critical item 6 with no finding, then unanswered items, then the conclusion.", "The conclusion, then unanswered items, then critical item 6 with no finding.", "Unanswered items, then the conclusion, then critical item 6 with no finding."]'::jsonb, 0, 'As recorded the refusal names the 4 unanswered items. With every item answered and the two blank Not applicable answers given reasons, it names critical item 6. With a finding raised from item 6 as well, it asks for the conclusion, and with the conclusion written the walk reads ALLOWED.'),
  ('compliance', 'intermediate', 'module', 'm05-the-audit-and-the-programme', 6, 'Every item on AUD-2026-007 is answered and a finding is raised from item 6. What does canReportAudit still ask for?', '["A finding raised from item 4, the Observation answer.", "The audit conclusion, which it calls the deliverable.", "The closure of AF-2026-018 before the report.", "A second auditor''s review of the whole checklist."]'::jsonb, 1, 'The refusal reads "Write the audit conclusion. It is the deliverable." With the conclusion written, the answer is ALLOWED.'),
  ('compliance', 'intermediate', 'module', 'm05-the-audit-and-the-programme', 7, 'Under canCloseAudit, which open findings hold a reported audit open?', '["Every open finding, observations included.", "Major nonconformities alone, whatever else stopped work.", "Any finding whose correction is not recorded.", "Major nonconformities, and any finding that stopped work."]'::jsonb, 3, 'Reported with both major findings open is refused, and so is reported with a stop-work minor finding open. A minor nonconformity or an observation open with no stop-work is ALLOWED.'),
  ('compliance', 'intermediate', 'module', 'm05-the-audit-and-the-programme', 8, 'canCloseAudit is asked to close an audit that has not been reported. What does it answer?', '["ALLOWED, provided no major finding is open.", "ALLOWED, provided the fieldwork is complete.", "REFUSED: Report the audit before closing it.", "REFUSED, until every finding it raised is closed."]'::jsonb, 2, 'The refusal reads "Report the audit before closing it: the report is the deliverable, and closure is the statement that everything it raised has been dealt with." The workflow allows Closed only from Reported.'),
  ('compliance', 'intermediate', 'module', 'm05-the-audit-and-the-programme', 9, 'What does auditIndependence compare?', '["The lead auditor against the author of the checklist.", "The lead auditor against the auditee.", "The auditee against the person who approved the programme.", "Every auditor on the team against every other one."]'::jsonb, 1, 'u-kelechi leading with u-boma audited is ALLOWED; u-boma named as both is refused: "The lead auditor is also the auditee for this audit."'),
  ('compliance', 'intermediate', 'module', 'm05-the-audit-and-the-programme', 10, 'An external lead auditor is named in text, with no account. What does auditIndependence answer?', '["ALLOWED for the external lead.", "REFUSED, since there is no account to test.", "REFUSED: Name the lead auditor.", "ALLOWED only once an account is made for them."]'::jsonb, 0, 'The digest prints ALLOWED for an external lead auditor named in text with no account. "Name the lead auditor." is the reporting refusal for an audit with no lead auditor named at all.'),
  ('compliance', 'intermediate', 'module', 'm05-the-audit-and-the-programme', 11, 'u-boma is named as both lead auditor and auditee, and auditIndependence refuses. What does the refusal leave to the person fixing it?', '["Nothing; it names the replacement lead auditor.", "Whether to cancel the audit or report it as it is.", "Whether an external auditor must be used.", "Which of the two roles gets somebody else."]'::jsonb, 3, 'The refusal ends "name somebody else as one or the other." The audit can keep its lead auditor and name a different auditee, or keep its auditee and name a different lead.'),
  ('compliance', 'intermediate', 'module', 'm05-the-audit-and-the-programme', 12, 'Which audits make up programmeProgress''s reported 3?', '["AUD-2026-002, AUD-2026-005 and AUD-2026-007.", "AUD-2026-001, AUD-2026-003 and AUD-2026-004.", "AUD-2026-001, AUD-2026-002 and AUD-2026-003.", "AUD-2026-002, AUD-2026-004 and AUD-2026-007."]'::jsonb, 2, 'AUD-2026-001 and AUD-2026-003 are Closed and AUD-2026-002 is Reported. A closed audit was reported on its way to closure, and it counts.'),
  ('compliance', 'intermediate', 'module', 'm05-the-audit-and-the-programme', 13, 'AUD-2026-004 is Cancelled. Where does programmeProgress count it?', '["In reported 3, since a cancelled audit has been dealt with.", "In outstanding 4, since it was never delivered.", "In overdue 3, since its planned end of 2026-06-19 has passed.", "In cancelled 1 alone."]'::jsonb, 3, 'programmeProgress prints total 8, reported 3, cancelled 1, outstanding 4, overdue 3, percent 38. The outstanding four are AUD-2026-005 to AUD-2026-008 and the overdue three are AUD-2026-005, AUD-2026-006 and AUD-2026-007.'),
  ('compliance', 'intermediate', 'module', 'm05-the-audit-and-the-programme', 14, 'The outstanding audits are reported except the last, AUD-2026-008, which is cancelled with no reason written. What does canCompleteProgramme answer?', '["REFUSED, naming AUD-2026-008 as not reported or cancelled.", "ALLOWED, since every audit now reads Reported, Closed or Cancelled.", "REFUSED, naming AUD-2026-004 as the audit with no reason.", "ALLOWED, with percent 38 left as it was."]'::jsonb, 0, 'The refusal reads "1 audit in this programme has not been reported or cancelled (AUD-2026-008)." A cancellation with no written reason leaves the audit outstanding, whatever its status reads.'),
  ('compliance', 'intermediate', 'module', 'm05-the-audit-and-the-programme', 15, 'What does approving an audit programme need on the record?', '["A lead auditor named for every audit in it.", "The date it was approved and who approved it.", "A written reason, the same as a cancellation.", "The date alone; the approver is taken from the author."]'::jsonb, 1, 'Approving with no date is refused with "Record the date the programme was approved." and with a date and no approver with "Name who approved it." With both, the answer is ALLOWED.'),
  ('compliance', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'Of the three open ABAM NCRs, which does canCloseNcr allow to close at the as-of date?', '["NCR-2026-031, whose corrective action k1 reads Complete.", "NCR-2026-027, a Minor NCR, which needs no root cause.", "NCR-2026-019, the oldest open NCR.", "None of them while QAP-2026-014 is Active."]'::jsonb, 2, 'NCR-2026-019 is Critical and reads ALLOWED with k4 verified effective. NCR-2026-031 is refused on its open action k2, and NCR-2026-027 on its missing disposition.'),
  ('compliance', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'NCR-2026-019 is 117 days old and NCR-2026-027 is 64 days old. What do the two ages tell a reader about closure?', '["Nothing. The older one may close at the as-of date and the younger one has no disposition.", "That NCR-2026-019 is the further from closure, since it sits in Over 90 days.", "That NCR-2026-027 will close first, since its band is the younger one.", "That both have stopped ageing, since each has a disposition recorded."]'::jsonb, 0, 'An open NCR ages until it closes, whatever step it has reached. To know what each still needs, read the closure answer and the actions: NCR-2026-019 reads ALLOWED, and NCR-2026-027 is refused on its disposition.'),
  ('compliance', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'checklistProgress prints outstanding 4 for AUD-2026-007, and the programme summarise prints answers outstanding 2. Why do they differ?', '["summarise counts only the Critical and Major items that are outstanding.", "summarise was given the 12 recorded answers, and items 13 and 14 have no row.", "summarise leaves out the two items whose Not applicable has no reason written beside it.", "summarise reads the programme at an earlier date than the checklist."]'::jsonb, 1, 'Items 10 and 11 have a recorded row that is not an answer, and those are the answers outstanding 2. checklistProgress reads all 14 questions and counts 10, 11, 13 and 14. Neither figure is wrong; each counts what it was given.'),
  ('compliance', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'The first canReportAudit refusal on AUD-2026-007 counts 4 items. Which printed figure counts the same four items?', '["The programme summarise''s answers outstanding 2.", "The programme summarise''s audits outstanding 4.", "checklistProgress''s notApplicable 3, with item 14.", "checklistProgress''s outstanding 4."]'::jsonb, 3, 'The refusal names items 10, 11, 13 and 14, the same four that unansweredItems lists and that checklistProgress counts as outstanding.'),
  ('compliance', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'At the as-of date, which statement about H-08 and H-11 is true?', '["They are overdue, and so they stop work.", "They are pending and on schedule, and they still stop work.", "They are on schedule, and so they do not yet stop work on the tie-in.", "They are resolved, and the plan waits only on its NCRs."]'::jsonb, 1, 'Both read Pending, resolved false and overdue false, and both are named in the hold point refusal. A hold point stops work until it is verified, whatever its planned date.'),
  ('compliance', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'What does NCR-2026-031 wait on at the as-of date, in the order the engine asks?', '["The check that k1 worked first, and after it k2, its late preventive action.", "Its disposition date, then k2, its preventive action due 2026-10-05.", "k2, its late preventive action, and then the check that k1 worked.", "A root cause, and then the check that k2 worked."]'::jsonb, 2, 'At the as-of date it is refused on "1 corrective or preventive action still open." With k2 Complete it is refused on "No corrective action has been verified effective yet." k1 reads Complete and verified effective false.'),
  ('compliance', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'Which percents do the tier''s three progress functions print for the Abam records at the as-of date?', '["planProgress 50, checklistProgress 71, programmeProgress 38.", "planProgress 38, checklistProgress 50, programmeProgress 71.", "planProgress 71, checklistProgress 38, programmeProgress 50.", "planProgress 75, checklistProgress 71, programmeProgress 38."]'::jsonb, 0, 'QAP-2026-014 reads resolved 6 and percent 50, AUD-2026-007''s checklist percent 71, and the programme reported 3 and percent 38. planProgress reads 75 only at the allowed closure step.'),
  ('compliance', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'Which of the tier''s progress functions print percent null over an empty record?', '["planProgress alone, and checklistProgress and programmeProgress both print 0.", "checklistProgress alone, and the other two refuse to count an empty record.", "None; each prints 0 over an empty record.", "All three: planProgress, checklistProgress and programmeProgress."]'::jsonb, 3, 'A plan with no points, no checklist at all and no audits each print percent null. An empty record has no fraction to take.'),
  ('compliance', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'A request to change a record is refused. What happens to the record?', '["The request is held as pending on the record until somebody corrects it.", "The record moves on to the requested status, with the refusal attached to it.", "Nothing changes, and the refusal says why the request was stopped.", "The item is marked Failed until the request is sent again."]'::jsonb, 2, 'A request is not a result. H-08 stays Pending after its refused pass, stays on the Active plan after its refused removal, and R-04 still reads Passed.'),
  ('compliance', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'The programme reads reported 3, cancelled 1 and percent 38. What does AUD-2026-004, the cancelled audit, add to the percent?', '["It counts as delivered, the same as a reported audit.", "Nothing. The percent counts reported audits, and it is not one.", "It counts as delivered once its cancellation reason is on the record.", "It counts as half an audit, between reported and outstanding."]'::jsonb, 1, 'Reported 3 counts AUD-2026-001, AUD-2026-002 and AUD-2026-003, and AUD-2026-004 sits in cancelled 1, in neither reported nor outstanding. A programme is delivered when its audits are reported, and the digest records that the programme counts reported audits only, which is why a complete programme that contains a cancelled audit reads below one hundred percent by design.'),
  ('compliance', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'What does the Expert tier put in place of this tier''s percents when it reads certification readiness?', '["A list of blockers, each one named.", "A percent of the clauses that are covered.", "A score in a band, like a risk rating.", "A count of the findings closed in the cycle."]'::jsonb, 0, 'The tier''s last lesson says readiness is a list of blockers, each one named, with no percent at all.'),
  ('compliance', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'A finding here feeds a risk register. Where does this course send a learner for risk scores and bands?', '["To the NCR summarise and its serious and open count.", "To ncrAgeing''s severity columns and its four age bands.", "To the programme summarise''s open major count.", "To the sibling course, Risk, Change & Learning."]'::jsonb, 3, 'Risk scores, bands and the approval rules for change belong to the sibling course, and this course sends the learner there for them.'),
  ('compliance', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'The plan''s summarise and programmeProgress both print overdue 3. Are they the same kind of record?', '["Yes. Both count the audits whose planned end has passed.", "No. One is H-05, S-10 and R-12; the other is AUD-2026-005 to AUD-2026-007.", "Yes. Both count the points whose planned date has passed.", "No. One counts NCRs and the other counts audit findings."]'::jsonb, 1, 'The plan''s overdue three are inspection points, and the programme''s overdue three are audits whose planned ends have passed and which have not been reported.'),
  ('compliance', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'On QAP-2026-014, which point reads both Failed and overdue true at the as-of date?', '["S-10, the site surveillance.", "R-12, the as-built dossier review.", "H-05, the radiography of the tie-in welds.", "H-08, the hydrostatic test, planned 2026-10-20."]'::jsonb, 2, 'H-05 is the one failed point and one of the overdue three with S-10 and R-12. S-10 reads In progress and R-12 Notified; H-08 reads Pending and overdue false.'),
  ('compliance', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'What stands between AUD-2026-007 and a report the engine allows, in the engine''s order?', '["Its unanswered items, a finding from item 6, and its conclusion.", "Its conclusion, a finding from item 2, and its closure.", "A finding from item 6, its closure, and its conclusion.", "Its unanswered items, the closure of AF-2026-018, and its lead auditor."]'::jsonb, 0, 'Items 13 and 14 need answers and items 10 and 11 their reasons, item 6 needs a finding, and the conclusion comes last. Finishing the fieldwork has not cleared overdue; reporting the audit will.'),
  ('compliance', 'intermediate', 'final', null, 1, 'H-08''s pass and W-09''s pass are each refused with nobody named. What do the two refusals both ask for?', '["A reason for the pass.", "A date and a named person.", "An NCR raised first.", "A future planned date."]'::jsonb, 1, 'H-08''s refusal asks for the date it was verified and who verified it; W-09''s asks for the date this was decided and who decided it. The words differ with the type and the pair underneath is the same.'),
  ('compliance', 'intermediate', 'final', null, 2, 'Which of these requests does canDecideCheckpoint allow?', '["W-09 waived with a reason and no date or verifier.", "H-11 set Not applicable with a date and a name, no reason.", "H-08 passed with nobody named on the record.", "H-08 waived with a date, a verifier and a reason."]'::jsonb, 3, 'The engine has no rule against waiving a hold point, and with its record and reason the waiver is ALLOWED. Each of the other three requests is refused for the part it lacks.'),
  ('compliance', 'intermediate', 'final', null, 3, 'Which statuses make up CHECKPOINT_RESOLVED_STATUSES?', '["Passed, Waived and Not applicable.", "Passed, Failed and Waived.", "Passed and Waived, and no other.", "Passed, Waived and In progress."]'::jsonb, 0, 'Failed is not resolved: H-05 is counted in failed 1 and among the outstanding 6. In progress and Notified are outstanding too.'),
  ('compliance', 'intermediate', 'final', null, 4, 'Which column on the QAP-2026-014 table does the engine derive from the point type alone?', '["overdue.", "resolved.", "stops work.", "planned."]'::jsonb, 2, 'BLOCKING_POINT_TYPES, the stop work list, holds one type, Hold point. stops work reads true on every Hold point row, whether Passed, Failed or Pending, and false on every other row whatever its status. resolved and overdue change as a point''s status and dates change.'),
  ('compliance', 'intermediate', 'final', null, 5, 'Once QAP-2026-014 is Closed, which of these is still allowed?', '["Raising an NCR against QAP-2026-014.", "Raising an NCR with no plan at all.", "Removing W-09, a pending witness point, from it.", "Moving the plan back to Active."]'::jsonb, 1, 'canRaiseNcr allows an NCR against no plan, and refuses one against the Closed plan. A closed plan''s points are frozen, and Closed is final in nextPlanStatuses.'),
  ('compliance', 'intermediate', 'final', null, 6, 'Which plan move in nextPlanStatuses goes back a step?', '["Active to Under review.", "Closed to Active.", "Superseded to Active.", "Under review to Draft."]'::jsonb, 3, 'A plan under review may return to Draft. Nothing leaves Closed or Superseded, and Active has no move back to Under review.'),
  ('compliance', 'intermediate', 'final', null, 7, 'TWO MODULES. The third plan refusal counts 3 open non-conformances, and the NCR summarise prints open 3. Are they the same NCRs?', '["No: the plan gate also counts NCR-2026-011, which is Voided.", "No: the plan gate counts only the two overdue NCRs and one other.", "Yes, the same three.", "No: summarise counts only NCRs that are serious and open."]'::jsonb, 2, 'Both counts are NCR-2026-031, NCR-2026-027 and NCR-2026-019, whatever their severity. NCR-2026-011, Voided, and the two Closed NCRs sit outside both.'),
  ('compliance', 'intermediate', 'final', null, 8, 'TWO MODULES. The plan gate counts NCRs as open. Which NCR status clears the plan gate without the NCR ever passing canCloseNcr?', '["Voided.", "Closed.", "Disposition agreed.", "Actions in progress."]'::jsonb, 0, 'The walk''s last step is every NCR closed or voided. NCR-2026-011 reads Voided with no disposition and k5 still Open, and canCloseNcr refuses an NCR with no disposition before anything else, so it reached Voided without passing that gate. Asked now, canCloseNcr answers "This non-conformance is already voided." Disposition agreed and Actions in progress read open, and the plan gate counts them.'),
  ('compliance', 'intermediate', 'final', null, 9, 'The failed-point rows put one other point Failed on a plan whose hold points are Passed and NCRs closed. Which of them lets the plan close?', '["S-10, the surveillance point, which stops nothing.", "M-07, the monitor point, already Not applicable once.", "R-04, the review point, since paper is not work.", "None of them."]'::jsonb, 3, 'Four rows, four refusals, one sentence. A point that stops nothing while pending still blocks the plan once it has Failed.'),
  ('compliance', 'intermediate', 'final', null, 10, 'At 2026-10-15, which NCRs read overdue true?', '["NCR-2026-031 and NCR-2026-027.", "NCR-2026-031 and NCR-2026-019.", "NCR-2026-019 and NCR-2026-011.", "NCR-2026-027 and NCR-2026-019."]'::jsonb, 1, 'NCR-2026-031 was due 2026-10-02 and NCR-2026-019 2026-09-30. NCR-2026-027 is due 2026-11-12, and NCR-2026-011 is Voided with no due date.'),
  ('compliance', 'intermediate', 'final', null, 11, 'Which NCR sits first in ncrByUrgency?', '["NCR-2026-031, Major, Actions in progress.", "NCR-2026-006, Minor, the earliest raised.", "NCR-2026-019, Critical, Disposition agreed.", "NCR-2026-027, Minor, the only Open one."]'::jsonb, 2, 'The three open NCRs take orders 1 to 3 with the Critical first, and the closed and voided NCRs follow at orders 4 to 6.'),
  ('compliance', 'intermediate', 'final', null, 12, 'An open NCR reaches an age of 31 days. What does ageBand read?', '["31 to 60 days.", "0 to 30 days, since 31 is its first day past the edge.", "61 to 90 days, the band the next month opens.", "null, since an edge day belongs to no band."]'::jsonb, 0, 'The digest''s edge rows print 30 days in 0 to 30 days and 31 days in 31 to 60 days.'),
  ('compliance', 'intermediate', 'final', null, 13, 'NCR-2026-011 was raised on 2026-05-11 and voided on 2026-05-13. What is its age?', '["None; a voided NCR has no age at all.", "It keeps ageing to the as-of date, since voided is not closed.", "2 days, until the dashboard moves it to Over 90 days.", "2 days."]'::jsonb, 3, 'Voiding stops the clock the way closing does. NCR-2026-011 reads 2 whatever the as-of date, and ncrAgeing leaves it out because it is no longer open.'),
  ('compliance', 'intermediate', 'final', null, 14, 'Which action is counted in the action summarise''s awaiting an effectiveness check 1?', '["k3, Complete and found ineffective on NCR-2026-019.", "k1, Complete on NCR-2026-031.", "k2, the preventive action In progress on NCR-2026-031.", "k5, the open action on the voided NCR-2026-011."]'::jsonb, 1, 'k1 reads Complete and verified effective false. k3 is the found ineffective 1 and k4 the verified effective 1.'),
  ('compliance', 'intermediate', 'final', null, 15, 'What is the least an Observation NCR needs on the record before canCloseNcr allows it?', '["The disposition, dated, and a root cause.", "The disposition, dated, and one corrective action.", "The disposition and its date, nothing more.", "The disposition, dated, and an action verified effective."]'::jsonb, 2, 'The Observation walk is the shortest: with Use as is and its date and nothing else it reads ALLOWED. With nothing recorded it meets the disposition refusal every NCR meets first.'),
  ('compliance', 'intermediate', 'final', null, 16, 'Which walks refuse an NCR that has its disposition and date but no root cause?', '["The Major walk and the Critical walk.", "Every walk, the Observation walk included.", "The Critical walk and no other.", "The Major, Critical and Minor walks."]'::jsonb, 0, 'The root cause refusals read "A major non-conformance needs a root cause before it closes." and the same with critical. The Minor walk prints ALLOWED for no root cause and no actions.'),
  ('compliance', 'intermediate', 'final', null, 17, 'The NCR summarise prints oldest open 117 days. Which NCR carries that age?', '["NCR-2026-006, the first NCR on the register to be raised.", "NCR-2026-011, raised 2026-05-11 and since Voided.", "NCR-2026-031, now overdue.", "NCR-2026-019, raised 2026-06-20."]'::jsonb, 3, 'The open ages are 43, 64 and 117, and NCR-2026-019, Disposition agreed, is the 117. NCR-2026-006 was raised first, on 2026-03-03, and its age stopped at 48 when it closed; NCR-2026-011 stopped at 2 when it was voided. NCR-2026-031 is open at 43.'),
  ('compliance', 'intermediate', 'final', null, 18, 'k6 is an open corrective action on NCR-2026-027, due 2026-11-01. Why is it not in the action summarise''s overdue 1?', '["Its NCR is Minor.", "It is not yet due: 2026-11-01 lies ahead.", "Its NCR has no disposition.", "It is a Corrective action, and overdue counts Preventive ones."]'::jsonb, 1, 'k6 reads open true and overdue false. The overdue one is k2, the preventive action on NCR-2026-031, due 2026-10-05.'),
  ('compliance', 'intermediate', 'final', null, 19, 'Which item is the observations 1 in checklistProgress on AUD-2026-007?', '["Item 4, the lifting plan, with the rigging sketch not attached.", "Item 9, excavation shoring, which carries its reason.", "Item 2, the gas test, with no entry for the 07:30 hot work.", "Item 14, the emergency drill, which has no answer."]'::jsonb, 0, 'Item 4 is Major and reads Observation, with the note "Plan approved; rigging sketch not attached." Item 9 is Not applicable and item 2 Nonconformant.'),
  ('compliance', 'intermediate', 'final', null, 20, 'Item 10''s note is blank and item 11 has no note at all. How does the engine treat the two?', '["Item 10 is answered, since a note field exists.", "Item 11 is answered, since Critical items need none.", "Alike: both read answered false.", "Both are answered, since each reads Not applicable."]'::jsonb, 2, 'A blank note counts the same as a missing one. Both sit in unansweredItems and both are named in the first reporting refusal.'),
  ('compliance', 'intermediate', 'final', null, 21, 'A finding carries a type and objective evidence and has no statement. What does canRaiseFinding answer?', '["REFUSED: Pick the finding type.", "ALLOWED, since the evidence says what was seen.", "REFUSED, until an owner and a due date are named for it.", "REFUSED: State the finding in one line."]'::jsonb, 3, 'canRaiseFinding refuses on no finding type, no one-line statement and no objective evidence, each with its own sentence.'),
  ('compliance', 'intermediate', 'final', null, 22, 'Does a finding''s grade alone decide whether it holds a reported audit open?', '["Yes. Only a major nonconformity holds a reported audit open.", "No. A minor finding that stopped work holds it open.", "Yes. Any open finding of any grade holds it open.", "No. An observation left open holds it open too."]'::jsonb, 1, 'Stopping work reaches past the grade: the row with a stop-work minor finding open reads REFUSED. With no stop-work, a minor nonconformity or an observation left open reads ALLOWED.'),
  ('compliance', 'intermediate', 'final', null, 23, 'TWO MODULES. A stop-work finding and a Major NCR each have a refusal that names a record. Which pairing is right?', '["The stop-work finding records its correction at the time; the Major NCR needs a corrective action for the cause.", "The stop-work finding needs a corrective action for the cause; the Major NCR records its correction at the time.", "Both need only a disposition, what happens to the item, before anything else is read.", "Both record a correction at the time, and neither asks for a corrective action."]'::jsonb, 0, 'The stop-work refusal reads "Imminent danger does not wait for the corrective action cycle." The Major NCR refusal reads "A disposition deals with the item; a corrective action deals with the cause."'),
  ('compliance', 'intermediate', 'final', null, 24, 'With AF-2026-018 raised from item 2, criticalAnswersWithoutFindings lists 6. What would raising a finding from item 6 as well let the reporting walk do?', '["Report the audit at once, the checklist being complete.", "Close the audit, since both critical items are covered.", "Move on to asking for the audit conclusion.", "Clear the overdue flag on AUD-2026-007."]'::jsonb, 2, 'Covering item 6 clears the critical-item step, and the next refusal asks for the conclusion. The report, and with it the end of overdue, comes only after that.'),
  ('compliance', 'intermediate', 'final', null, 25, 'From which statuses may an audit be Cancelled?', '["Any status that is not final, Reported included.", "Planned alone, before the fieldwork starts.", "Planned and In progress, before the fieldwork ends.", "Planned, In progress and Fieldwork complete."]'::jsonb, 3, 'Cancelling is open until the report is written. After that the audit''s one remaining move is to close.'),
  ('compliance', 'intermediate', 'final', null, 26, 'For an audit whose planned end has passed, which status is the first in the workflow to read overdue false?', '["Fieldwork complete.", "Reported.", "In progress.", "Closed."]'::jsonb, 1, 'The three statuses before the report read true past the planned end, and Reported, Closed and Cancelled read false. Reported comes first of those three.'),
  ('compliance', 'intermediate', 'final', null, 27, 'AUD-2026-008 is Planned and outstanding. Why is it not one of the programme''s overdue 3?', '["Its planned end, 2026-11-27, has not passed at the as-of date.", "A Planned audit is never overdue, whatever its planned end.", "It has no checklist yet, so there is nothing to be late on.", "It is the last audit, and the last one is counted on completion."]'::jsonb, 0, 'AUD-2026-006 is Planned too, with a planned end of 2026-10-02, and it reads overdue true. The overdue three are AUD-2026-005, AUD-2026-006 and AUD-2026-007.'),
  ('compliance', 'intermediate', 'final', null, 28, 'On four audits, Reported, Cancelled with no reason, Cancelled with a reason and Planned, how many does programmeProgress count outstanding, and which?', '["1: the Planned one, since both cancelled audits are dealt with.", "3: every audit except the Reported one.", "2: the Planned one and the one Cancelled with no reason.", "2: the two Cancelled ones, since neither was delivered."]'::jsonb, 2, 'One rule decides outstanding. programmeProgress counts 2, summarise counts 2, and canCompleteProgramme refuses on "2 audits in this programme have not been reported or cancelled." A cancellation without a written reason is outstanding, as AUD-2026-008 is when cancelled with none, and a Planned audit is outstanding, as AUD-2026-006 and AUD-2026-008 are named at the as-of date.'),
  ('compliance', 'intermediate', 'final', null, 29, 'An audit programme is Approved. What must happen before it can be marked Complete?', '["Nothing; Approved may move straight to Complete.", "It must first move to In progress.", "It must be Cancelled first.", "It must return to Draft for a second approval."]'::jsonb, 1, 'Approved may move to In progress or Cancelled, and only In progress may move to Complete. Complete and Cancelled are final.'),
  ('compliance', 'intermediate', 'final', null, 30, 'canCloseNcr is asked to close NCR-2026-022, which already reads Closed. What does it answer?', '["ALLOWED, since closing it again changes nothing on it.", "REFUSED: Agree the disposition first.", "ALLOWED, since its disposition is Use as is.", "REFUSED: This non-conformance is already closed."]'::jsonb, 3, 'The digest prints the same refusal for NCR-2026-006, also Closed, and "This non-conformance is already voided." for NCR-2026-011.'),
  ('compliance', 'intermediate', 'final', null, 31, 'TWO MODULES. What two rules about the lead auditor does this tier read?', '["There must be one, and it may not also be the auditee.", "There must be one with an account.", "It must be external.", "It may be the auditee with a co-signer."]'::jsonb, 0, 'One rule sits in the reporting gate, which refuses with "Name the lead auditor.", and one in auditIndependence, which allows an external lead auditor named in text with no account.'),
  ('compliance', 'intermediate', 'final', null, 32, 'canCompleteProgramme refuses the programme as recorded. Which audits does it name?', '["AUD-2026-005, AUD-2026-006 and AUD-2026-007, the overdue three.", "AUD-2026-004 alone, the cancelled audit.", "AUD-2026-005, AUD-2026-006, AUD-2026-007 and AUD-2026-008.", "AUD-2026-002, the one Reported and not yet Closed."]'::jsonb, 2, 'The refusal names the four audits that have not been reported or cancelled. AUD-2026-008 is outstanding with overdue false.'),
  ('compliance', 'intermediate', 'final', null, 33, 'TWO MODULES. Which three requests does the engine refuse until a written reason is on the record?', '["Passing a hold point, waiving a point, and cancelling an audit.", "Waiving a point, setting a hold point Not applicable, and cancelling an audit.", "Setting S-10 Not applicable, waiving a point, and approving a programme.", "Agreeing a disposition, cancelling an audit, and approving a programme."]'::jsonb, 1, 'A pass needs a date and a verifier, approval needs a date and an approver, and S-10 set Not applicable with nothing recorded is ALLOWED. A waiver, a set-aside hold point and a cancellation each need their reason.'),
  ('compliance', 'intermediate', 'final', null, 34, 'TWO MODULES. Which of these decisions does the engine accept with a date and a name and no reason?', '["Waiving W-09.", "Setting H-11 Not applicable.", "Cancelling AUD-2026-008.", "Passing H-08."]'::jsonb, 3, 'H-08 passed with a date and a verifier is ALLOWED. A waiver and a set-aside hold point need a reason as well, and a cancellation with no reason is refused.'),
  ('compliance', 'intermediate', 'final', null, 35, 'TWO MODULES. M-07 on the plan and item 10 on the checklist both read Not applicable. How does the engine count each?', '["M-07 counts as resolved; item 10 counts as unanswered without its reason.", "Both count as resolved or answered, since Not applicable is an accepted result.", "Both count as outstanding until a reason is written beside each.", "M-07 counts as outstanding; item 10 counts as answered."]'::jsonb, 0, 'M-07 is one of the resolved 6 under CHECKPOINT_RESOLVED_STATUSES. Item 10''s note is blank, it reads answered false, and it sits in unansweredItems.'),
  ('compliance', 'intermediate', 'final', null, 36, 'TWO MODULES. The plan gate reads NCRs and the audit gate reads findings. Which statement about the two closure gates is right?', '["Both wait on every open record raised against them, whatever its grade.", "The plan waits on Major NCRs alone; the audit waits on every open finding.", "The plan waits on every open NCR; the audit waits on open major and stop-work findings.", "Neither reads anything beyond its own points or its own checklist."]'::jsonb, 2, 'canClosePlan counts 3 open non-conformances whatever their severity, Minor NCR-2026-027 included. canCloseAudit allows a minor nonconformity or an observation open with no stop-work.'),
  ('compliance', 'intermediate', 'final', null, 37, 'TWO MODULES. What does percent 71 on the checklist and percent 50 on the plan each leave unsaid?', '["71 does not say how much was answered; 50 does not say how many points were resolved.", "71 leaves out the Nonconformant answers; 50 leaves out the Waived points.", "Nothing; each percent is the count of good results over the total.", "71 does not say what conformed; 50 does not say which points were waived."]'::jsonb, 3, 'Items 2 and 6, Nonconformant, sit inside answered 10. W-06 (Waived) and M-07 (Not applicable) sit inside resolved 6 beside the passes.'),
  ('compliance', 'intermediate', 'final', null, 38, 'A plan has 23 of its 40 points resolved. What percent does planProgress print for it?', '["38, the figure for 3 of 8.", "58.", "13, the figure for 1 of 8.", "63, the figure for 5 of 8."]'::jsonb, 1, 'Half up on the exact fraction gives 58 here, and that is the line the digest carries.'),
  ('compliance', 'intermediate', 'final', null, 39, 'At the as-of date canCloseNcr allows NCR-2026-019, a Critical NCR. Which record meets the last requirement of the Critical walk?', '["k4, verified effective.", "Its disposition, Return to supplier, agreed and dated.", "k3, marked Complete.", "Its place at order 1 in ncrByUrgency."]'::jsonb, 0, 'The Critical walk ends on a corrective action verified effective, after the disposition and its date, the root cause and a corrective action. On NCR-2026-019 k3 was checked and found ineffective, and k4 is the one action that reads verified effective true.'),
  ('compliance', 'intermediate', 'final', null, 40, 'H-08 is removed from QAP-2026-014 while the plan is still a Draft. What does canRemoveCheckpoint answer?', '["REFUSED, as it is on the Active plan.", "REFUSED until it is set Not applicable.", "ALLOWED only with a reason on the record.", "ALLOWED."]'::jsonb, 3, 'The hold point removal rule bites once a plan has left Draft. Before then H-08 may be taken off; after it, the route is Not applicable with its reason.'),
  ('compliance', 'intermediate', 'final', null, 41, 'TWO MODULES. The plan''s points and the NCR register each keep a count that survives closure. Which pairing is right?', '["overdue 3 on the Closed plan; open 3 over the closed NCRs.", "outstanding 6 on the Closed plan; concessions 2 over open NCRs.", "failed 1 on the Closed plan; concessions 2 over the closed NCRs.", "outstanding 6 on the Closed plan; mean open age 75 days over closed NCRs."]'::jsonb, 2, 'Under the plan marked Closed the points read outstanding 0, overdue 0, failed 1. concessions 2 are NCR-2026-022 and NCR-2026-006, both Closed.'),
  ('compliance', 'intermediate', 'final', null, 42, 'canReportAudit is asked about AUD-2026-007 with no lead auditor named at all. What does it answer?', '["ALLOWED, since the conclusion is written.", "REFUSED: Name the lead auditor.", "REFUSED: The lead auditor is also the auditee for this audit.", "ALLOWED, with an external auditor assumed."]'::jsonb, 1, 'A report is somebody''s report, and the reporting walk refuses the same audit with no lead auditor named. Independence is a second rule on top of it.');
